import sys, re
P = '/Users/cstokes/Desktop/settlement-engine/docs/DESIGN_FP_ARCH_CH.md'
t = open(P, encoding='utf-8').read()
TAG = '[ADDED 2026-10-20 (fp-final P6; L-CH-PD)'

def lines_idx(prefix):
    ls = t.split('\n')
    hits = [i for i, l in enumerate(ls) if l.startswith(prefix)]
    if len(hits) != 1:
        sys.exit(f'LINE PREFIX COUNT {len(hits)}: {prefix[:90]!r}')
    return ls, hits[0]

def insert_after(prefix, new):
    global t
    ls, i = lines_idx(prefix); ls.insert(i + 1, new); t = '\n'.join(ls)

def insert_before(prefix, new):
    global t
    ls, i = lines_idx(prefix); ls.insert(i, new); t = '\n'.join(ls)

def append_to(prefix, extra):
    global t
    ls, i = lines_idx(prefix); ls[i] = ls[i] + extra; t = '\n'.join(ls)

