# the WC INBOX cite fix (13) -> (14), every site on the corps rows (RULINGS-P5 §D.5)
FIX = ' [RE-POINTED 2026-10-20 (fp-final P6; L-CH-PD) — RULINGS-P5 §D.5: the fold numbers the corps\' WC half (14); its (13) is a gang gone over to a menace]'
ls = t.split('\n')
n = 0
for i, l in enumerate(ls):
    if '(13)' not in l or 're-pointed "(13)"' in l:
        continue
    if not ('WC INBOX' in l or 'row (13)' in l or "(13) the corps' four WC halves" in l):
        sys.exit(f'UNEXPECTED (13) at line {i+1}')
    k = l.count('(13)')
    ls[i] = l.replace('(13)', '(14)' + FIX)
    n += k
t = '\n'.join(ls)
if n != 10:
    sys.exit(f'CITE FIX COUNT {n} != 10')

open(P, 'w', encoding='utf-8').write(t)
print('pass 2 ok; cite sites', n, len(t.encode('utf-8')))
